import sys
input = sys.stdin.readline

def solve():
	(n, k) = map(int, input().split())
	arr = list(map(int, input().split()))
	if k <= n:
		lps = ans = 0
		for i in range(n):
			lps += arr[i]
			if i >= k:
				lps -= arr[i - k]
			ans = max(ans, lps)
		return ans + k * (k - 1) // 2
	else:
		ans = sum(arr) + (k - 1 + k - 1 - n + 1) * n // 2
		return ans
for _ in range(int(input())):
	print(solve())
